-- 4) 规则依赖：由目录 dataDependencies 自动生成（仅新增缺失的依赖关系）。
INSERT INTO t_system_config(config_key,config_type,config_version,config_value,config_schema_version,lifecycle_status,approval_status,is_active)
SELECT CONCAT('ALERT_RULE_CONTRACT:',SHA2(CONCAT(JSON_UNQUOTE(JSON_EXTRACT(c.config_value,'$.ruleCode')),CHAR(31),dep.contract_code),256)),
 'ALERT_RULE_CONTRACT','v1',JSON_OBJECT('required',1,'ruleCode',JSON_UNQUOTE(JSON_EXTRACT(c.config_value,'$.ruleCode')),'contractCode',dep.contract_code),
 'alert-rule-link-v1','ACTIVE','APPROVED',1
FROM t_system_config c
JOIN JSON_TABLE(c.config_value,'$.dataDependencies[*]' COLUMNS(contract_code VARCHAR(100) PATH '$')) dep
WHERE c.config_type='ALERT_RULE_CATALOG' AND JSON_UNQUOTE(JSON_EXTRACT(c.config_value,'$.sourceReference')) LIKE '用户反馈P0矩阵%'
ON DUPLICATE KEY UPDATE config_value=VALUES(config_value),is_active=1;

-- 5) 治理目录期望数量：42（原基线 + 6 条 risk-v1）→ 53（新增 11 条用户反馈 P0）。
UPDATE t_system_config
SET config_value = CAST('53' AS JSON),
    config_desc = '正式治理规则数（含用户反馈P0矩阵新增11条）',
    updated_at = NOW(3)
WHERE config_key = 'alert.governance.expected-rule-count'
  AND is_active = 1;
